SELECT 
FROM code_standard_version v
JOIN file_library_document d ON d.id = v.library_document_id
JOIN project p ON p.id = v.project_id
WHERE v.id = #{id}
  AND (
      p.owner_id = #{ownerId}
      OR EXISTS (
          SELECT 1 FROM project_member pm
          WHERE pm.project_id = p.id AND pm.user_id = #{ownerId}
      )
  )
  AND p.deleted = 0

SELECT COALESCE(MAX(version_no), 0)
FROM code_standard_version
WHERE standard_id = #{standardId}
